	var routeId=ReactAPI.getComponentAPI("Reference").APIs("patrolPlan.workRouteId.name").getValue();
	if(routeId.length==0){
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577359447120"));
		return false;
	}
	var patrolType=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.potrolType").getValue().value;
	//if(!patrolType){
	//	ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577086013087"));
	//	return false;
	//}
	if(patrolType=="PATROL_planType/single"){
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577358868777"));
		return false;
	}

	ReactAPI.createDialog("workItemRef", {
		title: ReactAPI.international.getText("PATROL.patrolRoute.WorkItem"),
		url: "/msService/PATROL/patrolRoute/workItem/workItemRef?routeId="+routeId[0].id+"&customConditionKey=routeId",
		size: 5,
		callback: function(data, event) {
			//callBackItem(data);
			console.log(data);
			var length=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getDatagridData().length;
			//周期
			var period="";
			//周期单位
			var periodUnit="";
			if(length>0){
				period=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getValueByKey(0,''period'');
				periodUnit=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getValueByKey(0,''periodUnit'');
			}
			itemCallBack(data,period,periodUnit);
			ReactAPI.destroyDialog("workItemRef");
		},
		isRef: true, // 是否开启参照
		buttons: [
			{
				text: ReactAPI.international.getText("Button.text.select"),
				type: "primary",
				//style: { color: "#fff", background: "#ff0000" },
				onClick: function(data) {
					var length=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getDatagridData().length;
					//周期
					var period="";
					//周期单位
					var periodUnit="";
					if(length>0){
						period=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getValueByKey(0,''period'');
						periodUnit=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getValueByKey(0,''periodUnit'');
					}
					console.log(data);
					itemCallBack(data,period,periodUnit);
					ReactAPI.destroyDialog("workItemRef");
				}
			},
			{
				text: ReactAPI.international.getText("Button.text.cancel"),
			    onClick: event => {
					ReactAPI.destroyDialog("workItemRef");
			    }
			}
		 ]
	});
