  if(res.code == 200){\n                                ReactAPI.destroyDialog(\"newDialog\");\n                                ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\").refreshDataByRequst({\n                                    type: \"post\",\n                                    url: \"/msService/PATROL/patrolRoute/workGroup/data-dg1575506219664\",\n                                    param: {datagridCode:\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\"}\n                                });\n                            }\n                        });\n                  }\n                },\n                {\n                  text: ReactAPI.international.getText(\"ec.common.cancel\"),\n                  onClick: event => {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                  }\n                }\n              ]\n            });\n        });\n    }","funcname":"onclick=''routeModify()''","buttonstyle":"modify","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1575535700568_8749","buttonoperationcode":"workGroupList_modify_modify_PATROL_1.0.0_patrolRoute_workGroupList","isHide":false,"showname":"修改","ecEnv":"product","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFJvdXRlX3dvcmtHcm91cExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"namekey":"com.supcon.orcid.audit.update","funcbody_es5":"function routeModify() {\n    //获取所选择的数据\n    var dataSelect = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\").getSelecteds();\n    //校验非本公司数据\n    if (!checkEditPower(dataSelect)) {\n        return false;\n    }\n    var selectRow = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\").getSelecteds();\n    if (selectRow.length == 0) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"ec.common.checkselected\"));\n        return false;\n    }\n    if (selectRow.length > 1) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"SupDatagrid.button.error\"));\n        return false;\n    }\n    ReactAPI.getPowerCode(\"workGroupList_add_add_PATROL_1.0.0_patrolRoute_workGroupList\", function (res) {\n        var pcParam = res[''workGroupList_add_add_PATROL_1.0.0_patrolRoute_workGroupList''];\n        var url = \"/msService/PATROL/patrolRoute/workGroup/workGroupEdit?__pc__=\" + pcParam + \"&viewCode=PATROL_1.0.0_patrolRoute_workGroupEdit&entityCode=PATROL_1.0.0_patrolRoute&iscrosscompany=false&openType=dialog&id=\" + selectRow[0].id;\n        ReactAPI.createDialog(\"newDialog\", {\n            title: ReactAPI.international.getText(\"PATROL.patrolRoute.WorkGroup\"),\n            size: 3,\n            url: url,\n            isRef: false, // 是否开启参照\n            buttons: [{\n                text: ReactAPI.international.getText(\"calendar.common.save\"),\n                type: \"primary\",\n                style: { color: \"#fff\", background: \"#58c9cb\" },\n                onClick: function onClick(event) {\n                    event.ReactAPI.submitFormData(\"save\", function (res) {\n                        console.log(res);\n                        if (res.code == 200) {\n                            ReactAPI.destroyDialog(\"newDialog\");\n                            ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\").refreshDataByRequst({\n                                type: \"post\",\n                                url: \"/msService/PATROL/patrolRoute/workGroup/data-dg1575506219664\",\n                                param: { datagridCode: \"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\" }\n                            });\n                        }\n                    });\n                }\n            }, {\n                text: ReactAPI.international.getText(\"ec.common.cancel\"),\n                onClick: function onClick(event) {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                }\n            }]\n        });\n    });\n}","id":"modify","operatetype":"CUSTOM","isconfirm":false,"CODE":"workGroupList_modify_modify_PATROL_1.0.0_patrolRoute_workGroupList","NAME":"修改","ICONCLS":"cui-btn-modify","USEINMORE":false,"SEPARATENUM":"0"},{"isSignatureConfig":true,"funcbody":"function workRouteDelete() {\n    //巡检路线表格\n    var routeTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\");\n    //巡检区域表格\n    var areaTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708\");\n    //巡检项表格\n    var itemTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041\");\n    //获取选中行\n    var selectRow = routeTable.getSelecteds();\n    if (selectRow.length == 0) {\n        //至少选择一条记录！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"ec.common.checkselected\"));\n        return false;\n    }\n    //校验非本公司数据\n    if (!checkEditPower(selectRow)) {\n    return false;\n    }\n    //组装参数\n    var routeList = new Array();\n    var routeIds = new Array();\n    selectRow.forEach(function (element, index) {\n        routeList.push({\n            index: index,\n            routeId: element.id\n        });\n        routeIds.push(element.id);\n    });\n    //校验巡检路线是否关联巡检计划\n    var checkStr = \"\";\n    ReactAPI.request(\n        {\n            type: \"post\",\n            url: \"/msService/PATROL/patrolRoute/workGroup/checkRelationPlan\",\n            async: false,\n            data: routeList\n        },\n        function (res) {\n            console.log(res);\n            if (res.code == 200) {\n                //请求成功\n                if (res.data) {\n                    res.data.forEach(function (element) {\n                        var route = selectRow[element.index];\n                        checkStr += \"<b>\" + route.name + \"</b>,\";\n                    });\n                }\n            } else {\n                //发生内部错误，请联系管理员！\n                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"greendill.show.title.500\"));\n            }\n        });\n    if (checkStr != \"\") {\n        //巡检路线[{0}]存在巡检计划，不允许删除！\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1611024814055\", checkStr.substr(0, (checkStr.length - 1))));\n        return false;\n    }\n    //弹出确认框\n    //确认删除吗？\n    ReactAPI.openConfirm({\n        //删除时将会同时删除巡检路线下的巡检区域和巡检项，确认删除吗？\n        message: ReactAPI.international.getText(\"PATROL.custom.randon1578725549579\"),\n        buttons: [\n            {\n                operatetype: \"yes\",\n                text: ReactAPI.international.getText(\"calendar.common.check\"),//确认\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                    //删除巡检路线\n                    //处理中...\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                    ReactAPI.request(\n                        {\n                            type: \"get\",\n                            url: \"/msService/PATROL/patrolRoute/workGroup/deleteWorkGroups?routeIds=\" + routeIds\n                        },\n                        function (res) {\n                            //关闭过度框\n                            ReactAPI.closeLoading();\n                            if (res.code == 200) {\n                                //处理成功\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n                                //刷新表格\n                                routeTable.refreshDataByRequst();\n                                areaTable.refreshDataByRequst();\n                                itemTable.refreshDataByRequst();\n\n                            } else {\n                                //发生内部错误，请联系管理员！\n                                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"greendill.show.title.500\"));\n                            }\n                        }\n                    );\n                }\n            },\n            {\n                operatetype: \"no\",\n                text: ReactAPI.international.getText(\"calendar.common.cancal\"),\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                }\n            },\n        ]\n    });\n}","funcname":"onclick=''workRouteDelete()''","buttonstyle":"del","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1575629511656_436","buttonoperationcode":"workGroupList_delete_del_PATROL_1.0.0_patrolRoute_workGroupList","isHide":false,"showname":"删除","ecEnv":"product","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFJvdXRlX3dvcmtHcm91cExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"namekey":"ec.print.template.delete","funcbody_es5":"function workRouteDelete() {\n    //巡检路线表格\n    var routeTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\");\n    //巡检区域表格\n    var areaTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708\");\n    //巡检项表格\n    var itemTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041\");\n    //获取选中行\n    var selectRow = routeTable.getSelecteds();\n    if (selectRow.length == 0) {\n        //至少选择一条记录！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"ec.common.checkselected\"));\n        return false;\n    }\n    //校验非本公司数据\n    if (!checkEditPower(selectRow)) {\n        return false;\n    }\n    //组装参数\n    var routeList = new Array();\n    v