    //巡检路线表格
    var routeTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664");
    //巡检区域表格
    var areaTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708");
    //巡检项表格
    var itemTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041");
    //获取选中行
    var selectRow = routeTable.getSelecteds();
    if (selectRow.length == 0) {
        //至少选择一条记录！
        ReactAPI.showMessage("w", ReactAPI.international.getText("ec.common.checkselected"));
        return false;
    }
    //校验非本公司数据
    if (!checkEditPower(selectRow)) {
    return false;
    }
    //组装参数
    var routeList = new Array();
    var routeIds = new Array();
    selectRow.forEach(function (element, index) {
        routeList.push({
            index: index,
            routeId: element.id
        });
        routeIds.push(element.id);
    });
    //校验巡检路线是否关联巡检计划
    var checkStr = "";
    ReactAPI.request(
        {
            type: "post",
            url: "/msService/PATROL/patrolRoute/workGroup/checkRelationPlan",
            async: false,
            data: routeList
        },
        function (res) {
            console.log(res);
            if (res.code == 200) {
                //请求成功
                if (res.data) {
                    res.data.forEach(function (element) {
                        var route = selectRow[element.index];
                        checkStr += "<b>" + route.name + "</b>,";
                    });
                }
            } else {
                //发生内部错误，请联系管理员！
                ReactAPI.showMessage("f", ReactAPI.international.getText("greendill.show.title.500"));
            }
        });
    if (checkStr != "") {
        //巡检路线[{0}]存在巡检计划，不允许删除！
        ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1611024814055", checkStr.substr(0, (checkStr.length - 1))));
        return false;
    }
    //弹出确认框
    //确认删除吗？
    ReactAPI.openConfirm({
        //删除时将会同时删除巡检路线下的巡检区域和巡检项，确认删除吗？
        message: ReactAPI.international.getText("PATROL.custom.randon1578725549579"),
        buttons: [
            {
                operatetype: "yes",
                text: ReactAPI.international.getText("calendar.common.check"),//确认
                type: "primary",
                onClick: function () {
                    ReactAPI.closeConfirm();
                    //删除巡检路线
                    //处理中...
                    ReactAPI.openLoading(ReactAPI.international.getText("EditView.notice.processing"));
                    ReactAPI.request(
                        {
                            type: "get",
                            url: "/msService/PATROL/patrolRoute/workGroup/deleteWorkGroups?routeIds=" + routeIds
                        },
                        function (res) {
                            //关闭过度框
                            ReactAPI.closeLoading();
                            if (res.code == 200) {
                                //处理成功
                                ReactAPI.showMessage("s", ReactAPI.international.getText("EditView.notice.operate.success"));
                                //刷新表格
                                routeTable.refreshDataByRequst();
                                areaTable.refreshDataByRequst();
                                itemTable.refreshDataByRequst();

                            } else {
                                //发生内部错误，请联系管理员！
                                ReactAPI.showMessage("f", ReactAPI.international.getText("greendill.show.title.500"));
                            }
                        }
                    );
                }
            },
            {
                operatetype: "no",
                text: ReactAPI.international.getText("calendar.common.cancal"),
                type: "primary",
                onClick: function () {
                    ReactAPI.closeConfirm();
                }
            },
        ]
    });
}]]></funcbody><funcname><![CDATA[onclick=''workRouteDelete()'']]></funcname><buttonstyle><![CDATA[del]]></buttonstyle><iscustomfunc><![CDATA[false]]></iscustomfunc><useInMore><![CDATA[false]]></useInMore><isPublished><![CDATA[false]]></isPublished><ispermission><![CDATA[false]]></ispermission><cellCode><![CDATA[cell_1575629511656_436]]></cellCode><buttonoperationcode><![CDATA[workGroupList_delete_del_PATROL_1.0.0_patrolRoute_workGroupList]]></buttonoperationcode><isHide><![CDATA[false]]></isHide><showname><![CDATA[删除]]></showname><regionType><![CDATA[BUTTON]]></regionType><iscallback><![CDATA[false]]></iscallback><namekey><![CDATA[ec.print.template.delete]]></namekey><funcbody_es5><![CDATA[function workRouteDelete() {
