    //巡检区域表格
    var areaTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708");
    //巡检项表格
    var itemTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041");
    //获取选中行
    var selectRow = areaTable.getSelecteds();
    if (selectRow.length == 0) {
        //至少选择一条记录！
        ReactAPI.showMessage("w", ReactAPI.international.getText("ec.common.checkselected"));
        return false;
    }

    //校验非本公司数据
    if (!checkEditPower(selectRow)) {
        return false;
    }

    var workAreaIds = new Array();
    selectRow.forEach(function (element) {
        workAreaIds.push(element.id);
    });
    //弹出确认框
    //确认删除吗？
    ReactAPI.openConfirm({
        //删除时将会同时删除该巡检区域下的巡检项，确认删除吗？
        message: ReactAPI.international.getText("PATROL.custom.randon1578730253444"),
        buttons: [
            {
                operatetype: "yes",
                text: ReactAPI.international.getText("calendar.common.check"),//确认
                type: "primary",
                onClick: function () {
                    ReactAPI.closeConfirm();
                    //删除巡检区域
                    //处理中...
                    ReactAPI.openLoading(ReactAPI.international.getText("EditView.notice.processing"));
                    ReactAPI.request(
                        {
                            type: "get",
                            url: "/msService/PATROL/patrolRoute/workArea/deleteWorkAreas?workAreaIds=" + workAreaIds
                        },
                        function (res) {
                            //关闭过度框
                            ReactAPI.closeLoading();
                            if (res.code == 200) {
                                //处理成功
                                ReactAPI.showMessage("s", ReactAPI.international.getText("EditView.notice.operate.success"));
                                //刷新表格
                                areaTable.refreshDataByRequst();
                                itemTable.refreshDataByRequst();

                            } else {
                                //发生内部错误，请联系管理员！
                                ReactAPI.showMessage("f", ReactAPI.international.getText("greendill.show.title.500"));
                            }
                        }
                    );
                }
            },
            {
                operatetype: "no",
                text: ReactAPI.international.getText("calendar.common.cancal"),
                type: "primary",
                onClick: function () {
                    ReactAPI.closeConfirm();
                }
            },
        ]
    });
}]]></funcbody><funcname><![CDATA[onclick=''workAreaDelete()'']]></funcname><buttonstyle><![CDATA[del]]></buttonstyle><iscustomfunc><![CDATA[false]]></iscustomfunc><useInMore><![CDATA[false]]></useInMore><isPublished><![CDATA[false]]></isPublished><ispermission><![CDATA[false]]></ispermission><cellCode><![CDATA[cell_1575630026861_2722]]></cellCode><buttonoperationcode><![CDATA[workGroupList_delete_del_PATROL_1.0.0_patrolRoute_workGroupList]]></buttonoperationcode><isHide><![CDATA[false]]></isHide><showname><![CDATA[删除]]></showname><regionType><![CDATA[BUTTON]]></regionType><iscallback><![CDATA[false]]></iscallback><namekey><![CDATA[ec.print.template.delete]]></namekey><funcbody_es5><![CDATA[function workAreaDelete() {
