ultVal'', '''');\n\t\t\tgridObj.setDatagridCellAttr(row, ''defaultVal'', { readonly: true });\n\t\t}\n\t\t//录入标准清除执行\n\t} else {\n\t\t//清空正常范围\n\t\tgridObj.setValueByKey(row, ''normalRange'', '''');\n\t\t//正常范围不可编辑\n\t\tgridObj.setDatagridCellAttr(row, ''normalRange'', { readonly: true });\n\t\t//自动判定赋值为false\n\t\tgridObj.setValueByKey(row, ''isAutoJudge'', false);\n\t\tgridObj.setDatagridCellAttr(row, ''isAutoJudge'', { readonly: true });\n\t\t//上限值和下限值不可编辑和清空\n\t\tgridObj.setValueByKey(row, ''upperLimit'', '''');\n\t\tgridObj.setValueByKey(row, ''lowerLimit'', '''');\n\t\tgridObj.setDatagridCellAttr(row, ''lowerLimit'', { readonly: true });\n\t\tgridObj.setDatagridCellAttr(row, ''upperLimit'', { readonly: true });\n\t\t//测温、测震不可编辑\n\t\t//测温、测震为空\n\t\tgridObj.setDatagridCellAttr(row, ''isThermometric'', { readonly: true });\n\t\tgridObj.setDatagridCellAttr(row, ''isSeismic'', { readonly: true });\n\t\tgridObj.setValueByKey(row, ''isSeismic'', false);\n\t\tgridObj.setValueByKey(row, ''isThermometric'', false);\n\t\t//默认值不可编辑\n\t\tgridObj.setValueByKey(row, ''defaultVal'', '''');\n\t\tgridObj.setDatagridCellAttr(row, ''defaultVal'', { readonly: true });\n\t}\n}","popView":false,"funcbody":"function setInputStarnderOnchange(value,row){\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507\");\n    //清空正常范围的值\n    table.setValueByKey(row,''normalRange'',null);\n    table.setValueByKey(row,''defaultVal'',null);\n    //去掉放大镜，如果有的话(默认值和正常范围)\n    $(\"input[id=''normalId\"+row+\"'']\").remove();\n    $(\"input[id=''defaultVal\"+row+\"'']\").remove();\n    if(value.length==0){\n        //清空 \n\t\ttable.setValueByKey(row,''isErrorBench'',null);\n\t\ttable.setValueByKey(row,''errorBenchUpper'',null);\n        //采集数据误差对标设置不可编辑\n        table.setDatagridCellAttr(row, \"isErrorBench\", { readonly: true });\n\t\ttable.setDatagridCellAttr(row, \"errorBenchUpper\", { readonly: true });\n        return\n    }\n    //获取录入标准的 值类型和编辑方式\n    \n    var inputStarnder = value[0];\n    //值类型\n    var valueType = inputStarnder.valType;\n    //编辑方式\n    var  editType = inputStarnder.editType;\n    if(valueType&&editType){\n        //值类型为 数字 编辑方式为 录入的 采集误差对标才设置 可编辑\n        if(valueType.id == ''PATROL_valueType/number''&&editType.id==''PATROL_editType/input''){\n            table.setDatagridCellAttr(row, \"isErrorBench\", { readonly: false })\n\t\t\ttable.setDatagridCellAttr(row, \"errorBenchUpper\", { readonly: false });\n        }else{\n\t\t\ttable.setValueByKey(row,''isErrorBench'',null);\n\t\t\ttable.setValueByKey(row,''errorBenchUpper'',null);\n            table.setDatagridCellAttr(row, \"isErrorBench\", { readonly: true });\n\t\t\ttable.setDatagridCellAttr(row, \"errorBenchUpper\", { readonly: true });\n        }\n    }\n}@@@@function setInputStarnder(obj,row){\n\t//判断是否存在后选址\n\tvar gridObj=ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507\");\n\tif(obj.length>0){\n\t\tvar editType=obj[0].editType.id;\n\t\tvar valueType=obj[0].valType.id;\n\t\tif(editType==\"PATROL_editType/singleSelect\"||editType==\"PATROL_editType/whether\"){//单选 \n\t\t\t//清空正常范围\n\t\t\tgridObj.setValueByKey(row,''normalRange'','''');\n\t\t\tgridObj.setDatagridCellAttr(row,''normalRange'',{readonly:false});\n\t\t\t//清空默认值\n\t\t\tgridObj.setValueByKey(row,''defaultVal'','''');\n\t\t\tgridObj.setDatagridCellAttr(row,''defaultVal'',{readonly:false});\n\t\t\t$(''div[data-key=\"defaultVal\"]'').eq(row+3).find(''input.ant-input'').attr(''readonly'',''readonly'')\n\t\t\t//自动判定可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''isAutoJudge'',{readonly:false});\n\t\t\t//自动判定赋值为true\n\t\t\tgridObj.setValueByKey(row,''isAutoJudge'',true);\n\t\t\t//上限值和下限值不可编辑和清空\n\t\t\tgridObj.setValueByKey(row,''upperLimit'','''');\n\t\t\tgridObj.setValueByKey(row,''lowerLimit'','''');\n\t\t\tgridObj.setDatagridCellAttr(row,''lowerLimit'',{readonly:true});\n\t\t\tgridObj.setDatagridCellAttr(row,''upperLimit'',{readonly:true});\n\t\t\t\n\t\t\t//测温、测震不可编辑\n\t\t\t//测温、测震为空\n\t\t\tgridObj.setDatagridCellAttr(row,''isThermometric'',{readonly:true});\n\t\t\tgridObj.setDatagridCellAttr(row,''isSeismic'',{readonly:true});\n\t\t\tgridObj.setValueByKey(row,''isSeismic'',false);\n\t\t\tgridObj.setValueByKey(row,''isThermometric'',false);\n\t\t}else if(editType==\"PATROL_editType/input\"&&valueType==\"PATROL_valueType/number\"){//录入且数值\n\t\t\t//清空正常范围\n\t\t\tgridObj.setValueByKey(row,''normalRange'','''');\n\t\t\t//正常范围可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''normalRange'',{readonly:false});\n\t\t\t//清空默认值\n\t\t\tgridObj.setValueByKey(row,''defaultVal'','''');\n\t\t\t//默认值可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''defaultVal'',{readonly:false});\n\t\t\t//自动判定赋值为true\n\t\t\tgridObj.setValueByKey(row,''isAutoJudge'',true);\n\t\t\t//自动判定可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''isAutoJudge'',{readonly:false});\n\t\t\t//上限值和下限值可编辑和清空\n\t\t\tgridObj.setValueByKey(row,''upperLimit'','''');\n\t\t\tgridObj.setValueByKey(row,''lowerLimit'','''');\n\t\t\tgridObj.setDatagridCellAttr(row,''lowerLimit'',{readonly:false});\n\t\t\tgridObj.setDatagridCellAttr(row,''upperLimit'',{readonly:false});\n\t\t\t\n\t\t\t//测温、测震可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''isThermometric'',{readonly:false});\n\t\t\tgridObj.setDatagridCellAttr(row,''isSeismic'',{readonly:false});\n\t\t}else{\n\t\t\t//清空正常范围\n\t\t\tgridObj.setValueByKey(row,''normalRange'','''');\n\t\t\t//正常范围不可编辑\n\t\t\tgridObj.setDatagridCellAttr(row,''normalRange'',{readonly:true});\n\t\t\t//自动判定赋值为false\n\t\t\tgridObj.setValueByKey(row,''isAutoJudge'',false);\n\t\t\tgridObj.setDatagridCellAttr(row,''isAutoJudge'',{readonly:true});\n\t\t\t//上限值和下限值不可编辑和清空\n\t\t\tgridObj.setValueByKey(row,''upperLimit'','''');\n\t\t\tgridObj.setValueByKey(row,''lowerLimit'','''');\n\t\t\tgridObj.setDatagridCellAttr(row,''lowerLimit'',{readonly:true});\n\t\t\tgridObj.setDatagridCellAttr(row,''upperLimit'',{readonly:true});\n\t\t\t//测温