rue });\n\t}\n\t//如果自动判定为否，则正常范围不可编辑\n\tif (!autojude) {\n\t\tdataObjects.setDatagridCellAttr(i, ''normalRange'', { readonly: true });\n\t}\n\n\t//值类型为 数字 编辑方式为 录入的 采集误差对标才设置 可编辑\n\tif (valueType == ''PATROL_valueType/number'' && editType == ''PATROL_editType/input'') {\n\t\tdataObjects.setDatagridCellAttr(i, \"isErrorBench\", { readonly: false });\n\t\tdataObjects.setDatagridCellAttr(i, \"errorBenchUpper\", { readonly: false });\n\t} else {\n\t\tdataObjects.setDatagridCellAttr(i, \"isErrorBench\", { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, \"errorBenchUpper\", { readonly: true });\n\t}\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}', 0, 0, 0, 'PATROL_1.0.0_patrolRoute_WorkItem_workId', 'PATROL_1.0.0_patrolRoute_WorkItem', '<?xml version="1.0" encoding="UTF-8"?><config><layout><layoutCode><![CDATA[layout_1619618721200_1016]]></layoutCode><listProperty><isCheckBox><![CDATA[true]]></isCheckBox><isEditable><![CDATA[true]]></isEditable><isTransverseShow><![CDATA[false]]></isTransverseShow><cannotAddNewRow><![CDATA[true]]></cannotAddNewRow><nodeExpanded><![CDATA[false]]></nodeExpanded><treePaging><![CDATA[false]]></treePaging><autoAddRow><![CDATA[false]]></autoAddRow><isFirstLoad><![CDATA[false]]></isFirstLoad><pendingDeal><![CDATA[false]]></pendingDeal><isTransCondition><![CDATA[false]]></isTransCondition><isEasyTable><![CDATA[false]]></isEasyTable><conditionContent><![CDATA[]]></conditionContent><importExcel><![CDATA[false]]></importExcel><canNotDeleteRow><![CDATA[true]]></canNotDeleteRow><canInsertRow><![CDATA[false]]></canInsertRow><exportExcel><![CDATA[false]]></exportExcel><maxTableHeight><![CDATA[0]]></maxTableHeight><widthType><![CDATA[]]></widthType><isTreeView><![CDATA[false]]></isTreeView><isSuperTable><![CDATA[false]]></isSuperTable><copyRow><![CDATA[false]]></copyRow><copyColumn><![CDATA[false]]></copyColumn><renderOver><![CDATA[//巡检项对象
var dataObjects=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507");
//pt长度
var length=dataObjects.getDatagridData().length;
for(var i=0;i<length;i++){
	//编辑方式
	var editType=dataObjects.getDatagridData()[i].inputStandardId.editType.id;
	//值类型
	var valueType=dataObjects.getDatagridData()[i].inputStandardId.valType.id;
	//自动判定
	var autojude=dataObjects.getDatagridData()[i].isAutoJudge;
	//录入可以编辑
	if(editType=="PATROL_editType/input" && valueType=="PATROL_valueType/number"){
		//正常范围可编辑
		dataObjects.setDatagridCellAttr(i,''normalRange'',{readonly:false});
		//默认值可编辑
		dataObjects.setDatagridCellAttr(i,''defaultVal'',{readonly:false});
		//自动判定可编辑
		dataObjects.setDatagridCellAttr(i,''isAutoJudge'',{readonly:false});
		//上限值和下限值可编辑和清空
		dataObjects.setDatagridCellAttr(i,''lowerLimit'',{readonly:false});
		dataObjects.setDatagridCellAttr(i,''upperLimit'',{readonly:false});

		//测温、测震可编辑
		dataObjects.setDatagridCellAttr(i,''isThermometric'',{readonly:false});
		dataObjects.setDatagridCellAttr(i,''isSeismic'',{readonly:false});
	}else if(editType=="PATROL_editType/singleSelect" || editType=="PATROL_editType/whether"){//单选
		//清空正常范围
		dataObjects.setDatagridCellAttr(i,''normalRange'',{readonly:false});
		//清空默认值
		dataObjects.setDatagridCellAttr(i,''defaultVal'',{readonly:false});
		//自动判定可编辑
		dataObjects.setDatagridCellAttr(i,''isAutoJudge'',{readonly:false});
		//上限值和下限值不可编辑和清空
		dataObjects.setDatagridCellAttr(i,''lowerLimit'',{readonly:true});
		dataObjects.setDatagridCellAttr(i,''upperLimit'',{readonly:true});

		//测温、测震不可编辑
		//测温、测震为空
		dataObjects.setDatagridCellAttr(i,''isThermometric'',{readonly:true});
		dataObjects.setDatagridCellAttr(i,''isSeismic'',{readonly:true});
		ReactAPI.request({
			type: "get",
			url: "/msService/PATROL/patrolRoute/workItem/isExeRuleWork?workItemId="+dataObjects.getValueByKey(i,''id''),
			async: false
		},
		function(msg) {
			if(msg.data.dealFlag==true){
				dataObjects.setDatagridCellAttr(i,''inputStandardId.code'',{readonly:true});
			}
		});
	}else{
		//清空正常范围
		dataObjects.setValueByKey(i,''normalRange'','''');
		//正常范围不可编辑
		dataObjects.setDatagridCellAttr(i,''normalRange'',{readonly:true});
		//自动判定赋值为false
		dataObjects.setValueByKey(i,''isAutoJudge'',false);
		dataObjects.setDatagridCellAttr(i,''isAutoJudge'',{readonly:true});
		//上限值和下限值不可编辑和清空
		dataObjects.setValueByKey(i,''upperLimit'','''');
		dataObjects.setValueByKey(i,''lowerLimit'','''');
		dataObjects.setDatagridCellAttr(i,''lowerLimit'',{readonly:true});
		dataObjects.setDatagridCellAttr(i,''upperLimit'',{readonly:true});
		//测温、测震不可编辑
		//测温、测震为空
		dataObjects.setDatagridCellAttr(i,''isThermometric'',{readonly:true});
		dataObjects.setDatagridCellAttr(i,''isSeismic'',{readonly:true});
		dataObjects.setValueByKey(i,''isSeismic'',false);
		dataObjects.setValueByKey(i,''isThermometric'',false);
		//默认值不可编辑
		dataObjects.setValueByKey(i,''defaultVal'','''');
		dataObjects.setDatagridCellAttr(i,''defaultVal'',{readonly:true});
	}
	//如果自动判定为否，则正常范围不可编辑
	if(!autojude){
		dataObjects.setDatagridCellAttr(i,''normalRange'',{readonly:true});
    }


    //值类型为 数字 编辑方式为 录入的 采集误差对标才设置 可编辑
    if(valueType == ''PATROL_valueType/number'' && editType==''PATROL_editType/input''){
        dataObjects.setDatagridCellAttr(i, "isErrorBench", { readonly: false })
        dataObjects.setDatagridCellAttr(i, "errorBenchUpper", { readonly: false });
    }else{
        dataObjects.setDatagridCellAttr(i, "isErrorBench", { readonly: true })
        dataObjects.setDatagridCellAttr(i, "errorBenchUpper", { readonly: true });
    }
}]]></renderOver><renderOver_es5><![CDATA[//巡检项对象
