ecimalPlace\");\n        //如果 小数位不为空 \n        if (decimalPlace || decimalPlace === 0) {\n            if (decimalPlace < 0) {\n                decimalPlace = 0;\n            }\n            if(value){\n                value = Number(value).toFixed(decimalPlace);\n                //修改页面显示\n                setTimeout(function(){\n                    editTable.setValueByKey(rowNum, \"concluse\", value)\n                });\n            }\n        }\n    }\n\n    //获取是否自动判断\n    var isAutoJudge = editTable.getValueByKey(rowNum, \"autoJudge\");\n    if (isAutoJudge && isAutoJudge == true) {\n        //获取正常范围\n        var normalRange = editTable.getValueByKey(rowNum, \"normalRange\");\n        if (value == null || value === \"\") {\n            editTable.setValueByKey(rowNum, \"realValue\", null);\n            editTable.setValueByKey(rowNum, \"realValue.value\", null);\n            return;\n        }\n        value = $.trim(value);\n        editTable.setValueByKey(rowNum, \"concluse\", value);\n        var isNormal = judge(valType, editType, value, normalRange);\n        var realValueid = \"\";\n        var realValue = \"\";\n        if(isNormal == true){\n            realValueid = \"PATROL_realValue/normal\";//正常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600907721\");\n        }else if (isNormal == false){\n            realValueid = \"PATROL_realValue/abnormal\";//异常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600915950\");\n        }\n        //下拉选择框时 一个realValue为向后台传入的值（页面显示不会改变），realValue.value 为页面展示的值（不会传入后台），所以都要设置\n        editTable.setValueByKey(rowNum, \"realValue\", { id: realValueid });\n        editTable.setValueByKey(rowNum, \"realValue.value\", realValue);\n    }\n}","showFormat":"TEXT","cellCode":"cell_1584600683983_3116","mneenable":false,"label":"实际结果","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFRh