    //获取表格对象
    var editTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503");
    //获取值类型
    var valType = editTable.getValueByKey(rowNum, "inputStandardId.valType");
    //获取编辑方式
    var editType = editTable.getValueByKey(rowNum, "inputStandardId.editType");
    //数字 录入 类型的有小数位,所以根据小数位对值进行处理
    if (valType.id === "PATROL_valueType/number" && editType.id === "PATROL_editType/input") {
        if(isNaN(value)){
            value = "";
            //修改页面显示
            setTimeout(function(){
                editTable.setValueByKey(rowNum, "concluse", value)
            });
        }
        //获取小数位
        var decimalPlace = editTable.getValueByKey(rowNum, "workItemId.inputStandardId.decimalPlace");
        //如果 小数位不为空
        if (decimalPlace || decimalPlace === 0) {
            if (decimalPlace < 0) {
                decimalPlace = 0;
            }
            if(value){
                value = Number(value).toFixed(decimalPlace);
                //修改页面显示
                setTimeout(function(){
                    editTable.setValueByKey(rowNum, "concluse", value)
                });
            }
        }
    }

    //获取是否自动判断
    var isAutoJudge = editTable.getValueByKey(rowNum, "autoJudge");
    if (isAutoJudge && isAutoJudge == true) {
        //获取正常范围
        var normalRange = editTable.getValueByKey(rowNum, "normalRange");
        if (value == null || value === "") {
            editTable.setValueByKey(rowNum, "realValue", null);
            editTable.setValueByKey(rowNum, "realValue.value", null);
            return;
        }
        value = $.trim(value);
        editTable.setValueByKey(rowNum, "concluse", value);
        var isNormal = judge(valType, editType, value, normalRange);
        var realValueid = "";
        var realValue = "";
        if(isNormal == true){
            realValueid = "PATROL_realValue/normal";//正常
            realValue = ReactAPI.international.getText("PATROL.systemCodevalue.randon1584600907721");
        }else if (isNormal == false){
            realValueid = "PATROL_realValue/abnormal";//异常
            realValue = ReactAPI.international.getText("PATROL.systemCodevalue.randon1584600915950");
        }
        //下拉选择框时 一个realValue为向后台传入的值（页面显示不会改变），realValue.value 为页面展示的值（不会传入后台），所以都要设置
        editTable.setValueByKey(rowNum, "realValue", { id: realValueid });
        editTable.setValueByKey(rowNum, "realValue.value", realValue);
    }
}]]></funcbody><showFormat><![CDATA[TEXT]]></showFormat><cellCode><![CDATA[cell_1584600683983_3116]]></cellCode><mneenable><![CDATA[false]]></mneenable><label><![CDATA[实际结果]]></label><isHidden><![CDATA[false]]></isHidden><columnType><![CDATA[TEXT]]></columnType><hide><![CDATA[false]]></hide><isrefselect><![CDATA[false]]></isrefselect><width><![CDATA[100]]></width><textalign><![CDATA[left]]></textalign><isCustom><![CDATA[false]]></isCustom><funcbody_es5><![CDATA[function change(value, rowNum) {
