    var itemTable = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507");
    //获取选中的行
    var selectedData = itemTable.getSelecteds();
    if(selectedData.length!=1){
        //请选择一条记录进行操作！
        ReactAPI.showMessage("w", ReactAPI.international.getText("SupDatagrid.button.error") );
        return;
    }
    //获取巡检区域的 路线id和设备id
    var areaTable = parent.ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708");
	var selectRow=areaTable.getSelecteds()[0].rowIndex;
    var deviceId=areaTable.getValueByKey(selectRow,''device.id'');
    var devide=areaTable.getValueByKey(selectRow,''device.name'');
    var workRouteId=areaTable.getValueByKey(selectRow,''workGroupId.id'');

