//如果已经保存，编码和值类型不允许修改
if (inputId) {
	//标准编码不允许编辑
	ReactAPI.getComponentAPI("Input").APIs("inputStandard.code").setReadonly(true);
	//值类型不允许编辑
	ReactAPI.getComponentAPI("SystemCode").APIs("inputStandard.valType").setReadonly(true);
