	valType = ReactAPI.getComponentAPI("SystemCode").APIs("inputStandard.valType").getValue().value;
}
var editType = "";
if (ReactAPI.getComponentAPI("SystemCode").APIs("inputStandard.editType").getValue()) {
	editType = ReactAPI.getComponentAPI("SystemCode").APIs("inputStandard.editType").getValue().value;
}

if (valType == ''PATROL_valueType/char'') {
	//小数位不允许编辑
