			ReactAPI.getComponentAPI("InputNumber").APIs("inputStandard.decimalPlace").setReadonly(false);
		} else {
			ReactAPI.getComponentAPI("InputNumber").APIs("inputStandard.decimalPlace").setReadonly(true);
		}
	}
