		return false;
	}

	var selectRow = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_inputStandard_inputStanList_inputStandard_sdg").getSelecteds();
	if (selectRow.length == 0) {
		//至少选择一条记录！
		ReactAPI.showMessage("w", ReactAPI.international.getText("ec.common.checkselected"));
		return false;
	}
	ReactAPI.request({
		type: "get",
