        type: "get",
        url: "/msService/PATROL/publicItem/publicItem/updateItemState?itemIds=" + idList + "&itemState=1&tableType=inputStand"
    }, function (msg) {
        if (msg.data.dealFlag == true) {
            ReactAPI.getComponentAPI("SearchPanel").APIs("PATROL_1.0.0_inputStandard_inputStanList_inputStandard_sp").updateSearch();
            ReactAPI.showMessage("s", ReactAPI.international.getText("foundation.language.enable.success"));
            return false;
        }
    });
