		//隐藏按月重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichWeek").setValue();
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekMonth").setValue();
		$(''div[data-key="patrolPlan.monthIntDay"]'').parents("tr").hide();
		$(''div[data-key="patrolPlan.monthIntWeek"]'').parents("tr").hide();
		//隐藏按周重复
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").setValue();
		$(''div[data-key="patrolPlan.weekInterval"]'').parents("tr").hide();
		//隐藏按天重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").setValue();
		$(''div[data-key="patrolPlan.day"]'').parents("tr").hide();
