VALUES ('PATROL_1.0.0_patrolPlan_patrolPlanView_layout_1609227701495_1_onload', 'product', 0, to_timestamp(1619618558913 / 1000.0), true, 'PATROL_1.0.0_patrolPlan', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('//无结束时
$(''div[data-key="patrolPlan.ownerPosition.valid"]'').parents("td").prev().children().html("");
$(''div[data-key="patrolPlan.ownerPosition.valid"]'').parents("td").prev().children().html(''<div class="ant-input-radio-input"><input type="radio" style="position: relative;top: -5px;" class="_2HIjZWVN" name="finishTime" value=1  checked onclick="finiTime()"></div>'');
//重复多少次结束
$(''div[data-key="patrolPlan.repeatNum"]'').children(":first").parents("td").prev().children().html("");
$(''div[data-key="patrolPlan.repeatNum"]'').children(":first").parents("td").prev().children().html(''<div class="ant-input-radio-input"><input type="radio" style="position: relative;top: -5px;" class="_2HIjZWVN" name="finishTime" value=2 onclick="finiTime()"></div>'');
//结束时间
$(''div[data-key="patrolPlan.endTime"]'').children(":first").parents("td").prev().children().html("");
$(''div[data-key="patrolPlan.endTime"]'').children(":first").parents("td").prev().children().html(''<div class="ant-input-radio-input"><input type="radio" style="position: relative;top: -5px;" class="_2HIjZWVN" name="finishTime" value=3 onclick="finiTime()"></div>'');

//按月重复
$(''div[data-key="patrolPlan.monthIntDay"]'').children(":first").parents("td").prev().prev().children().html('''');
$(''div[data-key="patrolPlan.monthIntDay"]'').children(":first").parents("td").prev().prev().children().html(''<div class="ant-input-radio-input"><input type="radio" style="position: relative;top: -5px;" class="_2HIjZWVN" name="monTime"  checked value=true onclick="monTime1()"></div>'');
$(''div[data-key="patrolPlan.monthIntWeek"]'').children(":first").parents("td").prev().prev().children().html('''');
$(''div[data-key="patrolPlan.monthIntWeek"]'').children(":first").parents("td").prev().prev().children().html(''<div class="ant-input-radio-input"><input type="radio" style="position: relative;top: -5px;" class="_2HIjZWVN" name="monTime" value=false onclick="monTime1()"></div>'');

//按天重复
//$(''div[data-key="patrolPlan.day"]'').children(":first").parents("td").prev().prev().children().html('''');
//$(''div[data-key="patrolPlan.day"]'').children(":first").parents("td").prev().prev().children().html(''<div class="ant-input-radio-input"><input type="radio" class="_2HIjZWVN" name="dayTime"  checked value=true onclick="daysTime()"></div>'');
//$(''div[data-key="patrolPlan.workDay"]'').children(":first").parents("td").prev().prev().children().html('''');
//$(''div[data-key="patrolPlan.workDay"]'').children(":first").parents("td").prev().prev().children().html(''<div class="ant-input-radio-input"><input type="radio" class="_2HIjZWVN" name="dayTime" value=false onclick="daysTime()"></div>'');

//按月隐藏
$(''div[data-key="patrolPlan.monthIntDay"]'').parents("tr").hide();
$(''div[data-key="patrolPlan.monthIntWeek"]'').parents("tr").hide();
//按周隐藏
$(''div[data-key="patrolPlan.weekInterval"]'').parents("tr").hide();
//按天隐藏
$(''div[data-key="patrolPlan.day"]'').parents("tr").hide();
//按照小时隐藏
$(''div[data-key="patrolPlan.hour"]'').parents("tr").hide();

//结束时间类型
var finishType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.finishTimeType").getValue().value;
//无结束时
if (finishType == "PATROL_finishType/none") {
	$(''input:radio[name="finishTime"]'').eq(0).trigger("click");
