//结束时间类型
var finishType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.finishTimeType").getValue().value;
//重复次数
if (finishType == "PATROL_finishType/repeatNum") {
	var times = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").getValue();
	if (!times) {
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576803073190");
	}
}
//结束时间
if (finishType == "PATROL_finishType/finishTime") {
	var endTime = ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").getValue();
	var startTime = ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.startTime").getValue();
	if (!endTime) {
		// 结束时间：结束时间不允许为空！</br>"
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576803630267");
	} else {
		if (!(endTime > startTime)) {
			//结束时间小于开始时间报错
			// "结束时间：结束时间必须大于开始时间！</br>"
			emessage += ReactAPI.international.getText("PATROL.custom.randon1576803706530");
		}
	}
}
//巡检模式
var patrolType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.potrolType").getValue().value;
//按小时重复
if (patrolType == "PATROL_planType/hour") {
	var hourTime = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").getValue(); //1
	if (hourTime == 0 || !hourTime) {
		// "重复模式：每几小时不允许为空！</br>"
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576807843221");
	}
	//按天重复
} else if (patrolType == "PATROL_planType/day") {
	//按天重复类型
	var dayType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.dayRepeatType").getValue().value;
	var day = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").getValue();
	var workDay = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").getValue();
	//按天重复
	if (dayType == "PATROL_dayRepeatType/day" && (day == 0 || !day)) {
		//重复模式：每几天不允许为空！</br>
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576808088024");
	}
	//按星期重复
	if (dayType == "PATROL_dayRepeatType/workDay" && (workDay == 0 || !workDay)) {
		//重复模式：每几工作日不允许为空！</br>
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576808336708");
	}
	//按周重复
} else if (patrolType == "PATROL_planType/week") {
	var weekTime = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.weekInterval").getValue();
	var weekDays = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").getValue();
	if (!weekTime || weekTime == 0) {
		//"重复模式：每几周不允许为空！</br>"
		emessage += ReactAPI.international.getText("PATROL.custom.randon1582695863933");
	} else if (!weekDays || weekDays === 0) {
		//"重复模式：每几周的周几不允许为空！</br>"
		emessage += ReactAPI.international.getText("PATROL.custom.randon1576817906709");
	}
	//按月重复
} else if (patrolType == "PATROL_planType/month") {
	//按月重复类型
	var monthType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.monthRepeatType").getValue().value;
	//按天重复
	if (monthType == "PATROL_monthRepeatType/day") {
		var months = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").getValue(); //1
		var days = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").getValue(); //1
		if (months == 0 || !months) {
			// "重复模式：每几月不允许为空！</br>"
			emessage += ReactAPI.international.getText("PATROL.custom.randon1582696521366");
		} else if (days == 0 || !days) {
			// "重复模式：每几月的第几天不允许为空！</br>"
			emessage += ReactAPI.international.getText("PATROL.custom.randon1576818815834");
