			emessage+=ReactAPI.international.getText("PATROL.custom.randon1576803706530");
		}
	}
}
//巡检模式
var patrolType=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.potrolType").getValue().value;
//按小时重复
if(patrolType=="PATROL_planType/hour"){
	var hourTime=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").getValue();//1
	if(hourTime==0 || !hourTime){
		// "重复模式：每几小时不允许为空！</br>"
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1576807843221");
	}
//按天重复
}else if(patrolType=="PATROL_planType/day"){
	//按天重复类型
	var dayType=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.dayRepeatType").getValue().value;
	var day=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").getValue();
	var workDay=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").getValue();
	//按天重复
	if(dayType=="PATROL_dayRepeatType/day" && (day==0 || !day)){
		//重复模式：每几天不允许为空！</br>
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1576808088024");
	}
	//按星期重复
	if(dayType=="PATROL_dayRepeatType/workDay" && (workDay==0 || !workDay)){
		//重复模式：每几工作日不允许为空！</br>
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1576808336708");
	}
	//按周重复
}else if(patrolType=="PATROL_planType/week"){
	var weekTime=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.weekInterval").getValue();
	var weekDays=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").getValue();
	if(!weekTime || weekTime==0){
        //"重复模式：每几周不允许为空！</br>"
        emessage+=ReactAPI.international.getText("PATROL.custom.randon1582695863933");
	}else if(!weekDays||weekDays===0){
		//"重复模式：每几周的周几不允许为空！</br>"
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1576817906709");
	}
	//按月重复
}else if(patrolType=="PATROL_planType/month"){
	//按月重复类型
	var monthType=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.monthRepeatType").getValue().value;
	//按天重复
	if(monthType=="PATROL_monthRepeatType/day"){
		var months=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").getValue();//1
		var days=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").getValue();//1
		if(months==0 || !months) {
           // "重复模式：每几月不允许为空！</br>"
            emessage+=ReactAPI.international.getText("PATROL.custom.randon1582696521366");
		}else if(days==0 || !days){
            // "重复模式：每几月的第几天不允许为空！</br>"
			emessage+=ReactAPI.international.getText("PATROL.custom.randon1576818815834");
		}else{
			if(days>31){
				//按月重复：每个月不允许超过31天！
				emessage+=ReactAPI.international.getText("PATROL.custom.randon1579393594747");
			}
		}
	//按星期重复
	}else if(monthType=="PATROL_monthRepeatType/week"){
		var monthss=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").getValue();//2
		var dayss=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichWeek").getValue();//2
		var weekDayss=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekMonth").getValue();
		if(monthss==0 || !monthss){
			// "重复模式：每几月不允许为空！</br>"
            emessage+=ReactAPI.international.getText("PATROL.custom.randon1582696521366");
		}else if(dayss==0 || !dayss){
			//每几月的第几周不为空
			emessage+=ReactAPI.international.getText("PATROL.custom.randon1582696562640");
		}else if(!weekDayss||weekDayss==0){
			 // "重复模式：每几月的第几周的周几不允许为空！</br>"
			emessage+=ReactAPI.international.getText("PATROL.custom.randon1576818879993");
		}else {
			if(dayss>5){
				//按月重复：每个月不允许超过6周！
				emessage+=ReactAPI.international.getText("PATROL.custom.randon1579394154425");
			}
		}
	}

}
console.log(999999);
//人员分配
var assignType=ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.staffAssignType").getValue().value;
if(assignType=="PATROL_staffAssign/staff"){
	var roleIds=ReactAPI.getComponentAPI("Reference").APIs("patrolPlan.patrolPlanRoleId").getValue();
	var staffIds=ReactAPI.getComponentAPI("Reference").APIs("patrolPlan.patrolPlanStaffId").getValue();
	//人员和角色都为空时
	if(roleIds.length==0 && staffIds.length==0){
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1577357663675");
	}
}else if(assignType=="PATROL_staffAssign/team"){
	var teamName=ReactAPI.getComponentAPI("Reference").APIs("patrolPlan.team.name").getValue();
	if(!teamName || teamName.length == 0){
		emessage+=ReactAPI.international.getText("PATROL.custom.randon1577357776648");
	}
}

if(emessage){
	ReactAPI.showMessage("f", emessage);
	return false;
}
//校验例外作业的周期必须为巡检周期的整数倍
var exePeriod=ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getValueByKey(0,''period'');
if(exePeriod){
	var num="";
	//天
	if("PATROL_planType/day"==patrolType ){
		num=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").getValue();

	//小时
	}else if("PATROL_planType/hour"==patrolType){
		num=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").getValue();

	//星期
	}else if("PATROL_planType/week"==patrolType){
		num=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.weekInterval").getValue();;

	//月
	}else if("PATROL_planType/month"==patrolType){
		num=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").getValue()==""?ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").getValue():ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").getValue();

	}
	if(exePeriod<num || exePeriod==num ||  exePeriod%num!=0){
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577102786139"));
		return false;
	}
}

//巡检提前开始时间
var advanceTime=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.advanceStartTime").getValue();
//巡检延迟结束时间
var delayTime=ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.delayStartTime").getValue();
//巡检提前开始时间和巡检延迟结束时间不允许同时为空
if(advanceTime && delayTime){
	ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1579071628809"));
	return false;
}', 'onsave')
