INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, button_code, event_function, name)
VALUES ('PATROL_1.0.0_patrolPlan_patrolPlanViewdg1609227703373_BUTTON_exceptionPeriodSet_onclick', 'product', 0, to_timestamp(1619618559025 / 1000.0), true, 'PATROL_1.0.0_patrolPlan', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function exceptionPeriodSet() {
	console.log(66666);
	var length = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getDatagridData().length;
	if (length == 0) {
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1578640178757"));
		return false;
	}
	if (!ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.potrolType").getValue()) {
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577086013087"));
		return false;
	}
	//选中的行
	var selectRow = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getSelecteds().length;
	if (selectRow < 1) {
		ReactAPI.showMessage("f", ReactAPI.international.getText("ec.expectedConsign.noSelected"));
		return false;
	}
	var patrolType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.potrolType").getValue().value;
	var planPeriod = "";
	var planPeriodUnit = "";
	//按小时重复
	if (patrolType == "PATROL_planType/hour") {
		planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").getValue(); //1
		planPeriodUnit = ReactAPI.international.getText("ec.entity.wf.hour");
		//按天重复
	} else if (patrolType == "PATROL_planType/day") {
		//按天重复类型
		var dayType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.dayRepeatType").getValue().value;
		//按天重复
		if (dayType == "PATROL_dayRepeatType/day") {
			planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").getValue();
			planPeriodUnit = ReactAPI.international.getText("PATROL.patrolPlan.PatrolPlan.day");
		}
		//按星期重复
		if (dayType == "PATROL_dayRepeatType/workDay") {
			planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").getValue();
			planPeriodUnit = ReactAPI.international.getText("foundation.calendar.workday");
		}
		//按周重复
	} else if (patrolType == "PATROL_planType/week") {
		planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.weekInterval").getValue();
		planPeriodUnit = ReactAPI.international.getText("ec.scheduler.job.intervalUnit.week");
		//按月重复
	} else if (patrolType == "PATROL_planType/month") {
		//按月重复类型
		var monthType = ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.monthRepeatType").getValue().value;
		planPeriodUnit = ReactAPI.international.getText("foundation.calendarWeekday.month");
		//按天重复
		if (monthType == "PATROL_monthRepeatType/day") {
			planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").getValue(); //1
			//按星期重复
		} else if (monthType == "PATROL_monthRepeatType/week") {
			planPeriod = ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").getValue(); //2
		}
	} else {
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577358868777"));
		return false;
	}
	if (!planPeriod || !planPeriodUnit) {
		ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1577086013087"));
		return false;
	}
	var exePeriodId;
	var url = "";
	if (ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").getDatagridData().length > 0) {
		exePeriodId = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").getDatagridData()[0].id;
	}

	if (exePeriodId) {
		url = "/msService/PATROL/patrolPlan/exceptPeriod/exceptionPerodEdit?planType=" + patrolType + "&planPeriod=" + planPeriod + "&planPeriodUnit=" + encodeURIComponent(planPeriodUnit) + "&id=" + exePeriodId;
	} else {
		url = "/msService/PATROL/patrolPlan/exceptPeriod/exceptionPerodEdit?planType=" + patrolType + "&planPeriod=" + planPeriod + "&planPeriodUnit=" + encodeURIComponent(planPeriodUnit);
	}
	ReactAPI.createDialog("newDialog", {
		title: ReactAPI.international.getText("PATROL.buttonPropertyshowName.randon1577083443201.flag"),
		size: 2,
		url: url,
		isRef: false, // 是否开启参照
		buttons: [{
			text: ReactAPI.international.getText("calendar.common.save"),
			type: "primary",
			style: { color: "#fff", background: "#58c9cb" },
			onClick: function onClick(event) {
				var period = event.ReactAPI.getComponentAPI("InputNumber").APIs("exceptPeriod.patrolPeriod").getValue();
				var excutePeriod = event.ReactAPI.getComponentAPI("InputNumber").APIs("exceptPeriod.period").getValue();
				if (excutePeriod) {
					if (excutePeriod < period || excutePeriod == period || excutePeriod % period != 0) {
						event.ReactAPI.getComponentAPI("InputNumber").APIs("exceptPeriod.period").setValidateStyle(''error'', ReactAPI.international.getText("PATROL.custom.randon1577102786139"));
						return false;
					} else {
						event.ReactAPI.getComponentAPI("InputNumber").APIs("exceptPeriod.period").setValidateStyle(''success'');
					}
				}
				event.ReactAPI.submitFormData("save", function (res) {

					if (!excutePeriod) {
						planPeriodUnit = '''';
					}
					//例外作业中选中的对象
					var objSelected = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getSelecteds();
					//例外作业中表格的长度
					var objALL = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").getDatagridData();

					//是否全选
					var flag = true;
					//例外作业周期记录是否删除
					var flagA = false;
					//例外作业是否保持不变
					var flagB = false;
					//例外作业周期记录是否删除
					var flagC = true;
					//例外作业中表格不是全部选中
					if (objSelected.length < objALL.length) {
						flag = false;
						for (var i = 0; i < objALL.length; i++) {
							if (objSelected.indexOf(objALL[i]) != -1) {
								ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").setRowData(i, { period: excutePeriod, periodUnit: planPeriodUnit });
							} else {
								if (objALL[i].period) {
									flagC = false;
									if (excutePeriod) {
										ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").setRowData(i, { period: excutePeriod, periodUnit: planPeriodUnit });
									}
								}
							}
						}
					} else {
						for (var i = 0; i < objALL.length; i++) {
							ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133").setRowData(i, { period: excutePeriod, periodUnit: planPeriodUnit });
						}
						//如果例外作业全选，并且例外周期都置为空，则将例外周期清空
						if (!excutePeriod) {
							flagA = true;
						}
					}
					//例外作业周期
					var length = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").getDatagridData().length;
					if (length == 0) {
						ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").addLine();
					}
					if (flag == true && flagA == true || flag == false && flagC == true && !excutePeriod) {
						ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").deleteLine();
					} else {
						if (!excutePeriod && flagC == false) {} else {
							ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362").setRowData(0, { period: excutePeriod, patrolPeriodUnit: planPeriodUnit });
						}
					}
					ReactAPI.destroyDialog("newDialog");
				});
			}
		}, {
			text: ReactAPI.international.getText("ec.common.cancel"),
			onClick: function onClick(event) {
				ReactAPI.destroyDialog("newDialog");
			}
		}]
	});
}', 'UTF8')), false, 'PATROL_1.0.0_patrolPlan_patrolPlanViewdg1609227703373_BUTTON_exceptionPeriodSet', lo_from_bytea(0, convert_to('function exceptionPeriodSet(){
