INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, field_code, event_function, name)
VALUES ('PATROL_1.0.0_patrolPlan_patrolPlan_EDIT_OTHER_PATROL_1.0.0_patrolPlan_PatrolPlan_potrolType_onchange', 'product', 0, to_timestamp(1619618558892 / 1000.0), true, 'PATROL_1.0.0_patrolPlan', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function poTypeChange(obj) {
	console.log(obj);
	//单次
	if (obj == "PATROL_planType/single") {
		//隐藏按月重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichWeek").setValue();
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekMonth").setValue();
		$(''div[data-key="patrolPlan.monthIntDay"]'').parents("tr").hide();
		$(''div[data-key="patrolPlan.monthIntWeek"]'').parents("tr").hide();
		//隐藏按周重复
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").setValue();
		$(''div[data-key="patrolPlan.weekInterval"]'').parents("tr").hide();
		//隐藏按天重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").setValue();
		$(''div[data-key="patrolPlan.day"]'').parents("tr").hide();
		//按小时重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").setValue();
		$(''div[data-key="patrolPlan.hour"]'').parents("tr").hide();
		//结束时间设置
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setValue();
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setReadonly(true);
		$(''input:radio[name="finishTime"]'').eq(1).trigger("click");
		$(''[name="finishTime"]'').attr("disabled", "disabled");
		// 选中重复几次模式
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setValue(1);
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setReadonly(true);
		//按小时重复
	} else if (obj == "PATROL_planType/hour") {
		//隐藏按月重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichWeek").setValue();
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekMonth").setValue();
		$(''div[data-key="patrolPlan.monthIntDay"]'').parents("tr").hide();
		$(''div[data-key="patrolPlan.monthIntWeek"]'').parents("tr").hide();
		//隐藏按周重复
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").setValue();
		$(''div[data-key="patrolPlan.weekInterval"]'').parents("tr").hide();
		//隐藏按天重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.day").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.workDay").setValue();
		$(''div[data-key="patrolPlan.day"]'').parents("tr").hide();
		//按小时重复
		$(''div[data-key="patrolPlan.hour"]'').parents("tr").show();
		//结束时间设置
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setReadonly(true);
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setValue();
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setReadonly(true);
		$(''input:radio[name="finishTime"]'').eq(0).trigger("click");
		$(''[name="finishTime"]'').removeAttr("disabled");
		//按天重复
	} else if (obj == "PATROL_planType/day") {
		//隐藏按月重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntWeek").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichDay").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.whichWeek").setValue();
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekMonth").setValue();
		$(''div[data-key="patrolPlan.monthIntDay"]'').parents("tr").hide();
		$(''div[data-key="patrolPlan.monthIntWeek"]'').parents("tr").hide();
		//隐藏按周重复
		ReactAPI.getComponentAPI("SystemCode").APIs("patrolPlan.weekDay").setValue();
		$(''div[data-key="patrolPlan.weekInterval"]'').parents("tr").hide();
		$(''div[data-key="patrolPlan.day"]'').parents("tr").hide();
		//隐藏按天重复
		$(''div[data-key="patrolPlan.day"]'').parents("tr").show();
		//按小时重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.hour").setValue();
		$(''div[data-key="patrolPlan.hour"]'').parents("tr").hide();
		$(''input:radio[name="dayTime"]'').eq(0).trigger("click");
		//结束时间设置
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setValue();
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.repeatNum").setReadonly(true);
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setValue();
		ReactAPI.getComponentAPI("DatePicker").APIs("patrolPlan.endTime").setReadonly(true);
		$(''input:radio[name="finishTime"]'').eq(0).trigger("click");
		$(''[name="finishTime"]'').removeAttr("disabled");
		//按周重复
	} else if (obj == "PATROL_planType/week") {
		//隐藏按月重复
		ReactAPI.getComponentAPI("InputNumber").APIs("patrolPlan.monthIntDay").setValue();
