INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, button_code, event_function, name)
VALUES ('PATROL_1.0.0_patrolPlan_potrolPlanList_BUTTON_stopRun_onclick', 'product', 0, to_timestamp(1619618558911 / 1000.0), true, 'PATROL_1.0.0_patrolPlan', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function stopRun() {
    //获取所选择的数据
    var dataSelect = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolPlan_potrolPlanList_patrolPlan_sdg").getSelecteds();
    //校验非本公司数据
    if (!checkEditPower(dataSelect)) {
