		if (workAreaId == undefined) {
			workAreaId = "";
		}
		ReactAPI.request({
			type: "get",
			url: "/msService/PATROL/patrolRoute/workArea/checkSameSignCode?signCode=" + obj + "&workAreaId=" + workAreaId + "&workGroupId=" + workGroupId
		}, function (res) {
