    //校验非本公司数据
    if (!checkEditPower(dataSelect)) {
        return false;
    }
    var selectRow = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041").getSelecteds();
    if (selectRow.length == 0) {
        //至少选择一条记录！
        ReactAPI.showMessage("w", ReactAPI.international.getText("ec.common.checkselected"));
        return false;
    }
    var idList = new Array();
    $(selectRow).each(function (index, element) {
        idList.push(selectRow[index].id);
    });
    var dealFlag = "";
    ReactAPI.request({
        type: "get",
        url: "/msService/PATROL/publicItem/publicItem/updateItemState?itemIds=" + idList + "&itemState=1&tableType=workItem"
