    var dataSelect = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg").getSelecteds();
   //校验非本公司数据
   if (!checkEditPower(dataSelect)) {
	return false;
    }

    //获取表格对象
    var table = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg");
    //获取选中的数据
    var selectData = table.getSelecteds();
    if (selectData.length == 0) {
        //请至少选中一行！
        ReactAPI.showMessage("w", ReactAPI.international.getText("Reference.confirm.tip.message"));
        return false;
    }
    var ids = "";
    for (var i = 0; i < selectData.length; i++) {
        var dataItem = selectData[i];
        var rowIndex = dataItem.rowIndex + 1;
        if (dataItem.isFault == true) {
            //第{0}行，巡检任务已生成隐患单，不能再次生成！
            ReactAPI.showMessage("w", ReactAPI.international.getText("PATROL.custom.danger.created", rowIndex));
            return false;
        }
        ids += dataItem.id + ",";
    }
    // 默认按钮
    ReactAPI.openConfirm({
        //"是否生成隐患单？"
        message: ReactAPI.international.getText("PATROL.custom.danger.isCreated"),
        onOk: function () {
            ReactAPI.closeConfirm();
            //生成隐患单
            var url = ''/msService/PATROL/patrolTask/taskDetail/createHiddenDanger'';
            var params = {
                ids: ids
            };
            //异步
            _postAsyncWithLoading(url, params, function (res) {
                if (res.code == 200) {
                    ReactAPI.showMessage("s", res.message);
                    //点击查询按钮
                    $("button[data-id=''query'']").click();
                } else {
                    ReactAPI.showMessage("f", res.message);
                }
            }, function (res) {
                ReactAPI.showMessage("f", res.responseJSON.message);
            }, ReactAPI.international.getText("PATROL.custom.danger.creating"));
        }
    });
}', 'onclick=''createTask()''')
