INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, button_code, event_function, name)
VALUES ('PATROL_1.0.0_patrolTask_batchChangeList_BUTTON_assignStaff_onclick', 'product', 0, to_timestamp(1619618558981 / 1000.0), true, 'PATROL_1.0.0_patrolTask', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function taskStaffChange() {
    //获取所选择的数据
    var dataSelect = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sdg").getSelecteds();
    //校验非本公司数据
    if (!checkEditPower(dataSelect)) {
        return false;
    }
    var staffSelectRow = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sdg").getSelecteds();
    //判断是否选中数据
    if (staffSelectRow.length == 0) {
        ReactAPI.showMessage("f", ReactAPI.international.getText("foundation.common.selectNullData"));
        return false;
    }
    for (var i = 0; i < staffSelectRow.length; i++) {
        var taskState = staffSelectRow[i].taskState.id;
        if ("PATROL_taskState/notIssued" != taskState) {
            ReactAPI.showMessage("f", ReactAPI.international.getText("PATROL.custom.randon1578984268384"));
            return false;
        }
    }
    //处理id数据变成数组数据传递
    var idList = new Array();
    var taskId = staffSelectRow[0].id;
    $(staffSelectRow).each(function (index, element) {
        idList.push(element.id);
    });
    var powerCode = "";
    var operateCode = "batchChangeList_assignStaff_add_PATROL_1.0.0_patrolTask_batchChangeList";
    ReactAPI.getPowerCode(operateCode, function (res) {
        powerCode = res[operateCode];
        var url = "/msService/PATROL/patrolTask/potrolTask/staffChangeEdit?__pc__=" + powerCode + "&id=" + taskId + "&idList=" + idList;
        ReactAPI.createDialog("newDialog", {
            title: ReactAPI.international.getText("PATROL.viewtitle.randon1578017423020"),
            size: 1,
            url: url,
            isRef: false, // 是否开启参照
            buttons: [{
                text: ReactAPI.international.getText("calendar.common.save"),
                type: "primary",
                style: { color: "#fff", background: "#58c9cb" },
                onClick: function onClick(event) {
                    console.log(11111111);
                    var staffIds = event.ReactAPI.getComponentAPI("Reference").APIs("potrolTask.patrolTaskStaffId").getValue();
                    if (staffIds.length == 0) {
                        event.ReactAPI.getComponentAPI("Reference").APIs("potrolTask.patrolTaskStaffId").setValidateStyle(''error'', ReactAPI.international.getText("PATROL.custom.randon1578194334198"));
                        return false;
                    } else {
                        event.ReactAPI.getComponentAPI("Reference").APIs("potrolTask.patrolTaskStaffId").setValidateStyle(''success'');
                    }
                    var staffList = new Array();
                    $(staffIds).each(function (index, element) {
                        staffList.push(element.id);
                    });
                    var idList = ReactAPI.getParamsInRequestUrl(event.window.location.href).idList;
                    ReactAPI.request({
                        type: "get",
                        url: "/msService/PATROL/patrolTask/potrolTask/staffBatchChange?staffList=" + staffList + "&idList=" + idList
                    }, function (res) {
                        event.ReactAPI.openLoading(ReactAPI.international.getText("ec.common.saving"));
                        setTimeout(function () {
                            event.ReactAPI.closeLoading();
                            ReactAPI.destroyDialog("newDialog");
                        }, 600);

                        ReactAPI.getComponentAPI("SearchPanel").APIs("PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sp").updateSearch();
                        //ReactAPI.destroyDialog("refDialog");
                    });
                }
            }, {
                text: ReactAPI.international.getText("ec.common.cancel"),
                onClick: function onClick(event) {
                    ReactAPI.destroyDialog("newDialog");
                }
            }]
        });
    });
}', 'UTF8')), false, 'PATROL_1.0.0_patrolTask_batchChangeList_BUTTON_assignStaff', lo_from_bytea(0, convert_to('function taskStaffChange(){
