                size:1 ,
                url: url,
                isRef: false, // 是否开启参照
                buttons: [
                {
                  text: ReactAPI.international.getText("calendar.common.save"),
                  type: "primary",
                  style: { color: "#fff", background: "#58c9cb" },
                  onClick: function(event) {
                    console.log(11111111);
                    debugger;
                    var changeState =event.ReactAPI.getComponentAPI(''SystemCode'').APIs(''potrolTask.taskState'').getValue().value;
                    var remark = event.ReactAPI.getComponentAPI(''TextArea'').APIs("potrolTask.remark").getValue();
                    var idList=ReactAPI.getParamsInRequestUrl(event.window.location.href).idList;
                    if(!changeState){
                        event.ReactAPI.getComponentAPI("SystemCode").APIs("potrolTask.taskState").setValidateStyle(''error'',ReactAPI.international.getText("PATROL.custom.randon1578030877786"));
                        return false;
                    }else{
                        event.ReactAPI.getComponentAPI("SystemCode").APIs("potrolTask.taskState").setValidateStyle(''success'');
                    }
                    ReactAPI.request({
                        type: "get",
                        url: "/msService/PATROL/patrolTask/potrolTask/taskStateUpdate?changeState="+changeState+"&remark="+remark+"&idList="+idList
                    },function(res) {
                        event.ReactAPI.openLoading(ReactAPI.international.getText("ec.common.saving"));
                        setTimeout(function(){
                            event.ReactAPI.closeLoading();
                            ReactAPI.destroyDialog("newDialog");
                        }, 600);


                        ReactAPI.getComponentAPI("SearchPanel").APIs("PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sp").updateSearch()
                        //ReactAPI.destroyDialog("refDialog");
                    });
                  }
                },
                {
                  text: ReactAPI.international.getText("ec.common.cancel"),
                  onClick: event => {
                    ReactAPI.destroyDialog("newDialog");
                  }
                }
              ]
            });
        });
    }', 'onclick=''taskStateChange()''')
