VALUES ('PATROL_1.0.0_patrolTask_taskOverviewListdg1586331011160_BUTTON_seeTrack_onclick', 'product', 0, to_timestamp(1619618559124 / 1000.0), true, 'PATROL_1.0.0_patrolTask', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function seeTrackClick(event) {
    var table = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_taskOverviewListdg1586331011160");
    //获取选中的行
    var selected = table.getSelecteds();
    if (selected.length != 1) {
        ReactAPI.showMessage("w", ReactAPI.international.getText("SupDatagrid.button.error"));
        return;
    }
    var selectData = selected[0];
    if (!(selectData.taskState.id == "PATROL_taskState/running" || selectData.taskState.id == "PATROL_taskState/completed")) {
        ReactAPI.showMessage("w", ReactAPI.international.getText("PATROL.custom.randon1598875840222"));
        return;
    }
    var taskId = selectData.id;
    ReactAPI.createDialog("newDialog", {
        title: ReactAPI.international.getText("PATROL.custom.randon1599008893449"), //"巡检轨迹"
        url: "/msService/SESGISConfig/themeConfig/themeLayers/index?themeCode=workRouteMap&displayMode=pureMap&inspectionTaskId=" + taskId,
        size: 6,
        isRef: false, // 是否开启参照
        buttons: [{
            text: ReactAPI.international.getText("Button.text.close"),
            type: "cancel",
            onClick: function onClick(event) {
                ReactAPI.destroyDialog("newDialog");
            }
        }]
    });
