	var selectRow = ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_tempTaskEditdg1578210699499").getSelecteds();
	if (selectRow.length == 0) {
		//至少选择一条记录！
		ReactAPI.showMessage("w", ReactAPI.international.getText("ec.entity.migrate.selectRecord"));
		return false;
	}
	var nrow = "";
	for (var i = 0; i < selectRow.length; i++) {
		nrow += selectRow[i].rowIndex + ",";
	}
	nrow = nrow.substring(0, nrow.length - 1);
	ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_tempTaskEditdg1578210699499").deleteLine(nrow);
	if (ReactAPI.getComponentAPI("SupDataGrid").APIs("PATROL_1.0.0_patrolTask_tempTaskEditdg1578210699499").getDatagridData().length == 0) {
		ReactAPI.getComponentAPI("Reference").APIs("potrolTask.workRoute.name").setReadonly(false);
