INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, button_code, event_function, name)
VALUES ('PATROL_1.0.0_publicItem_itemList_BUTTON_add_onclick', 'product', 0, to_timestamp(1619618558996 / 1000.0), true, 'PATROL_1.0.0_publicItem', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function itemAdd() {
	var selectedObj = ReactAPI.getComponentAPI("NavTree").APIs("PATROL_1.0.0_publicItem_itemLayout_publicItem_nt").getSelectedTreeNode();
	console.log(selectedObj);
	if (!selectedObj) {
		// ReactAPI.openNoun("提示", "请选择要操作的节点！", "w");
		ReactAPI.showMessage("w", ReactAPI.international.getText("BaseSet.material.Material.selectNodeBeOperate"));
		return false;
	}
	if (selectedObj.id != -1 && selectedObj.leaf) {
		//修改bug新增下级节点后，再新增公用项目可以增加
		ReactAPI.request({
			type: "get",
			url: "/msService/PATROL/publicItem/publicItemTree/checkItemTreeLeaf?treeId=" + selectedObj.id
		}, function (res) {
			if (res.data.isLeaf) {
				ReactAPI.getPowerCode("PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree", function (res) {
					var pcParam = res[''PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree''];
					var url = "/msService/PATROL/publicItem/publicItem/itemEdit?__pc__=" + pcParam + "&viewCode=PATROL_1.0.0_publicItem_itemLayout&entityCode=PATROL_1.0.0_publicItem&iscrosscompany=false&openType=dialog&itemTree.id=" + selectedObj.id;
					ReactAPI.createDialog("newDialog", {
						title: ReactAPI.international.getText("PATROL.publicItem.PublicItem"),
						size: 4,
						url: url,
						isRef: false, // 是否开启参照
						buttons: [{
							text: ReactAPI.international.getText("calendar.common.save"),
							type: "primary",
							style: { color: "#fff", background: "#58c9cb" },
							onClick: function onClick(event) {
								event.ReactAPI.submitFormData("save", function (res) {
									console.log(res);
									if (res.code == 200) {
										ReactAPI.destroyDialog("newDialog");
									}
								});
							}
						}, {
							text: ReactAPI.international.getText("ec.common.cancel"),
							onClick: function onClick(event) {
								ReactAPI.destroyDialog("newDialog");
							}
						}]
					});
				});
			} else {
				ReactAPI.showMessage("w", ReactAPI.international.getText("PATROL.custom.randon1575340035936"));
				return false;
			}
		});
	} else {
		ReactAPI.showMessage("w", ReactAPI.international.getText("PATROL.custom.randon1575340035936"));
		return false;
	}
}', 'UTF8')), false, 'PATROL_1.0.0_publicItem_itemList_BUTTON_add', lo_from_bytea(0, convert_to('function itemAdd(){
