		ReactAPI.showMessage("w", ReactAPI.international.getText("BaseSet.material.Material.selectNodeBeOperate"));
		return false;
	}
	if(selectedObj.id!=-1 && selectedObj.leaf){
		//修改bug新增下级节点后，再新增公用项目可以增加
		ReactAPI.request({
			type: "get",
			url: "/msService/PATROL/publicItem/publicItemTree/checkItemTreeLeaf?treeId="+selectedObj.id
		},function(res) {
			if(res.data.isLeaf){
					ReactAPI.getPowerCode("PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree", function(res) {
					var pcParam=res[''PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree''];
					var url="/msService/PATROL/publicItem/publicItem/itemEdit?__pc__="+pcParam+"&viewCode=PATROL_1.0.0_publicItem_itemLayout&entityCode=PATROL_1.0.0_publicItem&iscrosscompany=false&openType=dialog&itemTree.id="+selectedObj.id;
