INSERT INTO public.runtime_event (code, ec_env, version, modify_time, valid, entity_code, module_code, event_function_es5, proj_flag, button_code, event_function, name)
VALUES ('PATROL_1.0.0_publicItem_itemTree_BUTTON_add_onclick', 'product', 0, to_timestamp(1619618558994 / 1000.0), true, 'PATROL_1.0.0_publicItem', 'PATROL_1.0.0', lo_from_bytea(0, convert_to('function addPublicItemTree() {
	console.log(111111);
	var selectedObj = ReactAPI.getComponentAPI("NavTree").APIs("PATROL_1.0.0_publicItem_itemLayout_publicItem_nt").getSelectedTreeNode();
	if (!selectedObj) {
		// ReactAPI.openNoun("提示", "请选择要操作的节点！", "w");
		ReactAPI.showMessage("w", ReactAPI.international.getText("BaseSet.material.Material.selectNodeBeOperate"));
		return false;
	}
	var hasItem = "";
	ReactAPI.request({
		type: "get",
		url: "/msService/PATROL/publicItem/publicItem/hasItemAndIsLeaf?treeId=" + selectedObj.id
	}, function (msg) {
		hasItem = msg.data.hasItem;
	});
	setTimeout(function () {
		if (hasItem) {
			// 该目录已存在公用项目，无法添加新目录！
			ReactAPI.showMessage("w", ReactAPI.international.getText("PATROL.custom.randon1575291490834"));
			return false;
		}
		ReactAPI.getPowerCode("PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree", function (res) {
			var pcParam = res[''PATROL_1.0.0_publicItem_itemLayout_itemTree_add_add_PATROL_1.0.0_publicItem_itemTree''];
			var url = "/msService/PATROL/publicItem/publicItemTree/itemTreeEdit?__pc__=" + pcParam + "&viewCode=PATROL_1.0.0_publicItem_itemTreeEdit&parentId=" + selectedObj.id;
			ReactAPI.createDialog("newDialog", {
				title: ReactAPI.international.getText("PATROL.viewdisplayName.randon1575005435568"),
